insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('des-zaad-mi-owe', 'Des zaad mi owe!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das zerrt mich runter!', '[{"kategorie": "wörtlich", "text": "\"Das zieht mich runter!\"  2. Das drückt auf meine Stimmung!  3. Das zieht mich emotional in den Keller!"}]'::jsonb, ''),
  ('bei-mir-wiad-ned-owezaad', 'Bei mir wiad ned owezaad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei mir wird nicht hinabgezerrt!', '[{"kategorie": "wörtlich", "text": "\"Bei mir wird die Säge nicht hinab, sondern hinauf gezerrt!\""}, {"kategorie": "fig.", "text": "Bei mir wird nicht gebummelt oder geschlampt!  3. Bei mir wird Gas gegeben, nicht getrödelt!  4. Bei mir wird nicht [[tachiniert]]!"}]'::jsonb, ''),
  ('bei-mir-wiad-ned-tachiniad', 'Bei mir wiad ned tachiniad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei mir wird nicht tachiniert!', '[{"kategorie": "wörtlich", "text": "\"Bei mir wird nicht gebummelt oder geschlampt!\"  2. Bei mir wird nicht getändelt!  3. Bei mir wird Gas gegeben, nicht getrödelt!  4. [[Bei]] mia wiad ned owezaad!"}]'::jsonb, ''),
  ('des-is-a-owezaara-wiara-im-biachl-schdeed-dea-daedad-soebst-iwan-heagott-im-himmae-schlecht-reedn', 'Des is a Owezaara wiara im Biachl schdeed - dea dädad söbst iwan Heagott im Himmä schlecht reedn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist ein Abwärtszerrer, wie er im Buche steht - täte selbst über den Herrgott im Himmel schlecht reden!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Miesmacher, wie er im Buche steht - der würde sogar den Herrgott im Himmel schlechtreden!\"  2. \"Das ist ein chronischer Grantler - der würde selbst im Paradies noch meckern!\"  3. \"Das ist ein Dauernörgler durch und durch - der findet an allem was Schlechtes!\""}]'::jsonb, ''),
  ('darwaeu-mia-uns-noo-olle-in-oasch-aufreissn-vaschwind-dea-owezaara-wiara-schaas-aus-da-reitan', 'Darwäu mia uns noo olle in Oasch aufreissn, vaschwind dea Owezaara wiara Schaas aus da Reitan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Derweil wir uns noch alle den Arsch aufreißen, verschwindet dieser Drückeberger wie ein Schas aus der Reitern!', '[{"kategorie": "wörtlich", "text": "\"Während wir uns noch alle den Arsch aufreißen, hat sich dieser Wappler wie ein Furz in Luft aufgelöst!\"  2. \"Während wir noch alle schuften, ist dieser [[Tachinierer]] schon sang- und klanglos verschwunden!\"  3. \"Wir hackeln bis zum Umfallen, und dieser [[Wappler]] macht sich dezent aus dem Staub!\""}]'::jsonb, ''),
  ('in-leffae-ogeem', 'in Leffä ogeem', '', '', '', 'Tod und Sterben auf Wienerisch', 'den Löffel abgeben', '[{"kategorie": "wörtlich", "text": "\"sterben\" (im Mittelalter hatte jeder seinen eigenen selbstgeschnitzten Löffel, mit dem er sich beim Armeleuteessen frei bedienen durfte. Diesen höchsteigenen Löffel wegzulegen, war gleichbedeutend mit dem Tod)"}, {"kategorie": "scherzhaft für", "text": "\"das Zeitliche segnen\", [[ein]] Bankerl reißen, [[die]] Patschen strecken, [[die]] Eisen aufstellen, [[ins]] Gras beißen"}]'::jsonb, ''),
  ('iagendwaunn-miass-ma-olle-in-leffae-oogeem-i-wueue-nua-ned-da-easchde-sei', 'Iagendwaunn miass ma olle in Leffä oogeem - I wüü nua ned da Easchde sei!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Irgendwann müssen wir alle den Löffel abgeben - ich will nur nicht der Erste sein!', '[{"kategorie": "wörtlich", "text": "\"Irgendwann werden wir alle das Zeitliche segnen - ich will nur nicht der Erste sein!\"  2. Abkratzen müssen wir alle irgendwann – aber bitte nicht ich zuerst!  3. Irgendwann beißen wir alle ins Gras - ich will nur nicht als Erster drunterliegen!"}]'::jsonb, 'in Leffä ogeem'),
  ('i-hau-mi-oo', 'I hau mi oo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich haue mich ab!', '[{"kategorie": "scherzhaft für", "text": "\"Ich lach mich krumm und bucklig!\"  2. Ich kann mich vor Lachen nicht mehr halten!  3. Ich lach mir einen [[Ast]]!  4. [[I peck mi oo!]]"}]'::jsonb, ''),
  ('i-baea-mi-oo', 'I bäa mi oo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich bäre mich ab!', '[{"kategorie": "scherzhaft für", "text": "\"Ich hau mich ab!\"  2. \"Ich lach mich krumm und bucklig!\"  3.  Ich kann mich vor Lachen nicht mehr halten!  4. Ich lach mir einen [[Ast]]!  5. [[I peck mi oo!]]"}]'::jsonb, 'I peck mi oo!'),
  ('i-peck-mi-oo', 'I peck mi oo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich pecke mich ab!', '[{"kategorie": "wörtlich", "text": "\"Ich hau mich ab!\"  2. \"Ich lach mich krumm und bucklig!\"  3. Ich kann mich vor Lachen nicht mehr halten!  4. Ich lach mir einen [[Ast]]!  5. [[I bäa mi oo!]]"}]'::jsonb, 'I hau mi oo!'),
  ('de-hoosn-owelossn', 'de Hoosn owelossn', '', '', '', 'Wiener Sprüche, die sitzen!', 'die Hose runterlassen', '[{"kategorie": "wörtlich", "text": "\"die Hose nach unten gleiten lassen\", herunterziehen, abstreifen"}, {"kategorie": "fig.", "text": "Farbe bekennen,  mit der Wahrheit rausrücken, Klartext sprechen"}, {"kategorie": "in Bezug auf Personen", "text": "\"sich so geben, wie man wirklich ist\", sein Innerstes offenbaren, sein wahres Gesicht zeigen, die Maske fallen lassen"}, {"kategorie": "Kartenspielerjargon", "text": "alle Karten aufdecken, sein Blatt offenlegen, \"zeigen, was man hat\""}]'::jsonb, 'Loss de Hoosn a Schdickl owe, damit i s''Gummibandl eiziang kaunn!'),
  ('loss-de-hoosn-a-schdickl-owe-damit-i-s-gummibandl-eiziang-kaunn', 'Loss de Hoosn a Schdickl owe, damit i s''Gummibandl eiziang kaunn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Lass die Hose ein Stück weit runter, damit ich das Gummiband einziehen kann!', '[{"kategorie": "wörtlich", "text": "\"Zieh die Hose ein Stück nach unten, damit ich das Gummiband einsetzen kann!\"  2. Bitte schieb die Hose etwas runter, damit ich das Gummiband einlegen kann!  3. Zieh die Hose ein bisschen runter, damit ich das Gummiband einfädeln kann!"}]'::jsonb, 'de Hoosn owelossn'),
  ('jetzt-haassds-hoosn-owelossn', 'Jetzt haassds ''Hoosn owelossn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Jetzt heißt es ''Hose runterlassen''!', '[{"kategorie": "wörtlich", "text": "\"Jetzt heißt''s: ''Hose runter''!\"  2. Jetzt heißt''s: ''Alle Karten auf den Tisch!''\"  3. Jetzt heißt''s: ''Farbe bekennen''!\"  4. Jetzt heißt''s: ''Maske runter''!\""}]'::jsonb, ''),
  ('loss-de-hoosn-owe', 'Loss de Hoosn owe!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Lass die Hose runter!', '[{"kategorie": "wörtlich, in Bezug auf Personen", "text": "\"Lass die Hosen runter!\"  2. Lass die Maske fallen!  3. Gib dich so, wie du wirklich bist!\"  4. Zeige ungeniert dein wahres Ich!  3. (Kartenspiel) Decke deine Karten auf!"}]'::jsonb, 'de Hoosn owelossn'),
  ('lossds-de-hoosn-owe-de-schdich-ghean-olle-mia', 'Lossds de Hoosn owe, de Schdich ghean olle mia!', '', '', '', 'Wiener Kartentipplerjargon', 'Lasst die Hosen runter, die Stiche gehören alle mir!', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Deckt eure Karten auf, die Stiche gehören alle mir!\"  2. Legt eure Karten auf den Tisch – alle Stiche sind meine!  3. Aufdecken, Leute – die Runde gehört mir!"}]'::jsonb, 'de Hoosn owelossn'),
  ('oogschmoizane-kneedl', 'oogschmoizane Kneedl', '', '', '', 'Wiener Küche & Gaumenfreuden', 'abgeschmalzene Knödel', '[{"kategorie": "wörtlich", "text": "\"Knödel, die mehrmals in heißem Schmalz gewendet wurden\" (vom althochdeutschen \"smalz\"=\"ausgelassenes Fett\")"}, {"kategorie": "", "text": "in erhitztem Fett geschwenkte Knödel"}]'::jsonb, ''),
  ('hea-auf-zum-rean', 'Hea auf zum Rean!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hör auf zu rehren!', '[{"kategorie": "wörtlich", "text": "\"Hör auf zu weinen!\"  2. Reiß dich zusammen!  3. Hör auf mit dem Geheule!  4. Hör auf zu flennen!"}]'::jsonb, ''),
  ('si-ooschdruudln', 'si ooschdruudln', '', '', '', 'Grundwortschatz Wienerisch', 'sich abstrudeln', '[{"kategorie": "wörtlich", "text": "\"sich wie in einem Strudel im Kreis drehen\" (vom mittelhochdeutschen \"strudel\"=\"Wirbel\")"}, {"kategorie": "fig.", "text": "sich abmühen, sich abplagen, sich abrackern, sich kaputtarbeiten, sich [[abnudeln]]"}]'::jsonb, 'I schdruudl mi oo wiara Deppada!'),
  ('i-schdruudl-mi-oo-wiara-deppada', 'I schdruudl mi oo wiara Deppada!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich strudle mich ab wie ein Depperter!', '[{"kategorie": "", "text": "Ich schufte wie ein Idiot!  2. Ich rackere wie ein Wahnsinniger!  3. Ich schinde mich ab wie ein Depp!"}]'::jsonb, ''),
  ('mei-oowosch-schaud-so-aus-wia-da-letzte-toog-vuam-woeoeduntagaung', 'Mei Oowosch schaud so aus wia da letzte Toog vuam Wööduntagaung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Meine Abwasch sieht so aus wie der letzte Tag vorm Weltuntergang!', '[{"kategorie": "wörtlich", "text": "\"Meine Spüle sieht so aus wie der letzte Tag vorm Weltuntergang!\"  2. Die Spüle ist ready fürs Dschungelcamp – inklusive Kleintieren!  3. Die Spüle sieht aus wie ‘ne WG nach 6 Wochen ohne Mitbewohner!"}]'::jsonb, ''),
  ('maunche-soong-wia-schdaumman-vom-offn-oo-owa-i-glaub-da-off-wueue-des-ned-zuageem', 'Maunche soong, wia schdaumman vom Offn oo - owa I glaub, da Off wüü des ned zuageem!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Manche sagen, wir stammen vom Affen ab - aber ich glaub, der Affe will das aber nicht zugeben!', '[{"kategorie": "wörtlich", "text": "\"Manche sagen, wir stammen vom Affen ab – aber der Affe hat das längst dementiert!\"  2. Manche sagen, wir kommen vom Affen – der Affe sagt, er will einen Vaterschaftstest!  3. Der Affe sieht uns Menschen und denkt: ''Oh nein, was hab ich getan…''"}]'::jsonb, ''),
  ('i-reed-ned-mit-offn-de-si-fia-professoan-hoidn', 'I reed ned mit Offn, de si fia Professoan hoidn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich red nicht mit Affen, die sich für Professoren halten!', '[{"kategorie": "wörtlich", "text": "\"Ich rede nicht mit Idioten, die sich für Genies halten!\"  2. Ich diskutiere nicht mit Leuten, die ihren IQ im Lotto gewonnen haben!  3. Nur weil der Affe ''ne Brille trägt, ist er noch lange kein Einstein!"}]'::jsonb, ''),
  ('i-hob-an-off-sitzn', 'I hob an Off sitzn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich habe einen Affen sitzen', '[{"kategorie": "wörtlich", "text": "\"Ich habe einen mächtigen Rausch;\"  2. Ich bin dicht bis unters Dach!  3. Ich bin voll wie zehn Russen!  4. Ich bin abgefüllt bis zum Anschlag!"}]'::jsonb, ''),
  ('botanisch-gseeng-is-de-ogroosl-a-beean', 'Botanisch gseeng, is de Ogroosl a Beean!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Botanisch gesehen, ist die Abgrasel eine Beere!', '[{"kategorie": "wörtlich", "text": "\"Botanisch gesehen, ist die Abgrasel eine Beerenfrucht!\"  2. Aus botanischer Sicht zählt die Stachelbeere zu den echten Beeren!  3. Rein pflanzlich betrachtet, ist die Stachelbeere eine Frucht vom Typ Beere!"}]'::jsonb, ''),
  ('de-ogroosl-aun-da-schaunk-hod-mi-auglaechld-drei-zeend-weniga-und-ma-haedads-fia-halloween-buchn-kenna', 'De Ogroosl aun da Schaunk hod mi auglächld - drei Zeend weniga, und ma hädads fia Halloween buchn kenna!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Abgrasel an der Schank hat mich angelächelt – drei Zähne weniger und man hätte sie für Halloween buchen können!', '[{"kategorie": "wörtlich", "text": "\"Das abgepflückte Frauenzimmer an der Theke hat mich angelächelt – drei Zähne weniger und man hätte sie für Halloween buchen können!\"  2. Dieses verwitterte Frauenzimmer an der Theke grinste mich an – ich zuckte, dachte kurz, es sei ein Halloween-Special!  3. Die Vogelscheuche an der Schank hat mich angelächelt wie ‘ne kaputte Kürbislaterne – nur mit mehr Alkohol im Atem!"}]'::jsonb, ''),
  ('ia-lossds-eich-heaschbueuen-wia-schuibuam-so-untaiadisch-schbueued-ned-amoi-de-aeagste-ogrooslmaunnschoft-aus-da-untaliiga', 'Ia lossds eich heaschbüün wia Schuibuam - so untaiadisch schbüüd ned amoi de äagste Ogrooslmaunnschoft aus da Untaliiga!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ihr lasst euch herspielen wie Schulbuben – so unterirdisch spielt nicht einmal die ärgste Abgraselmannschaft aus der Unterliga!', '[{"kategorie": "wörtlich", "text": "\"Ihr lasst euch herspielen wie Schulbuben – so unterirdisch spielt nicht einmal die ärgste Gurkentruppe aus der Unterliga!\"  2. Ihr spielt wie Schulmädchen auf Klassenausflug – jede [[Eiermannschaft]] aus der Bezirksliga würde mehr Widerstand leisten!  3. Ihr wurdet vernascht wie ein Frühstückskipferl – jede Wirtshausmannschaft hätte euch an die Wand gespielt!"}]'::jsonb, ''),
  ('sogoa-maeuwiaf-schbueuen-auf-an-haeaecharen-nivoo-ois-diise-eiamaunnschofd', 'Sogoa Mäuwiaf schbüün auf an häächaren Nivoo ois diise Eiamaunnschofd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Selbst Maulwürfe spielen auf einem höheren Niveau als diese Eiermannschaft!', '[{"kategorie": "wörtlich", "text": "\"Selbst Maulwürfe spielen auf einem höheren Niveau als diese unterirdische Mannschaft!\"  2. Diese Eiermannschaft war so unterirdisch, dass sich selbst Maulwürfe für sie fremdgeschämt haben!  3. Da unten, wo diese unterirdische Mannschaft spielt, graben sonst nur noch Maulwürfe!"}]'::jsonb, ''),
  ('oiso-ealich-mit-dera-ogrooslpartii-kaunnst-heechstns-eadaepfaen-eantn-owa-kaan-fuassboi-schbueuen', 'Oiso ealich, mit dera Ogrooslpartii kaunnst heechstns Eadäpfän eantn, owa kaan Fuassboi schbüün!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Also ehrlich, mit dieser Abgraselpartie kannst du höchstens Erdäpfeln ernten, aber keinen Fußball spielen!', '[{"kategorie": "wörtlich", "text": "\"Also ehrlich, mit der Gurkentruppe kannst du höchstens Kartoffeln ernten, aber keinen Fußball spielen!\"  2. Mit der Truppe gewinnst du keinen Pokal, höchstens den Kartoffelsack-Wettbewerb!  3. Mit dieser Wirtshaustruppe ist nicht mal ein Blumentopf zu gewinnen!"}]'::jsonb, ''),
  ('so-a-ogrooslpartii-siichst-sunst-ned-amoi-in-da-kreisliga', 'So a Ogrooslpartii siichst sunst ned amoi in da Kreisliga!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'So eine Abgraselpartie siehst du sonst nicht einmal in der Kreisliga!', '[{"kategorie": "wörtlich", "text": "\"So eine unterirdische Partie sieht man sonst nicht einmal in der Kreisliga!\"  2. Ein derart unterirdisches Fußballmatch hätte man selbst in der Kreisliga schon nach 45 Minuten abgepfiffen!  3. Jedes Match in der Kreisliga ist besser als diese Schlafwagenpartie!"}]'::jsonb, ''),
  ('so-a-eiapartii-siichst-sunst-ned-amoi-in-da-kreisliga', 'So a Eiapartii siichst sunst ned amoi in da Kreisliga!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'So eine Eierpartie siehst du sonst nicht einmal in der Kreisliga!', '[{"kategorie": "wörtlich", "text": "\"So eine unterirdische Partie sieht man sonst nicht einmal in der Kreisliga!\"  2. Ein derart unterirdisches Fußballmatch hätte man selbst in der Kreisliga schon nach 45 Minuten abgepfiffen!  3. Jedes Match in der Kreisliga ist besser als diese Schlafwagenpartie!"}]'::jsonb, ''),
  ('waunn-scheenheid-im-auge-des-betrochtas-liigd-daunn-soit-ma-bei-dera-ogrooslpartii-de-aung-liawa-zua-lossn', 'Waunn Scheenheid im Auge des Betrochtas liigd, daunn soit ma bei dera Ogrooslpartii de Aung liawa zua lossn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Wenn Schönheit im Auge des Betrachters liegt, sollte man bei dieser Abgraselpartie die Augen lieber zu lassen!', '[{"kategorie": "wörtlich", "text": "\"Wenn Schönheit im Auge des Betrachters liegt, sollte man bei dieser verwitterten Damenrunde die Augen lieber zu lassen!\"  2. Diese Damenrunde war derart verwittert, da hätte man eher Denkmalschutz als Make-up gebraucht!  3. Wenn der liebe Gott Humor hat, hat er uns diese Vogelscheuchen-Truppe nur zum Schmäh geschickt!"}]'::jsonb, ''),
  ('wos-fiara-eiamaetsch-kaa-tempo-nui-ideen-reina-schlofwoongfuassboi', 'Wos fiara Eiamätsch - kaa Tempo, nui Ideen, reina Schlofwoongfuassboi!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Was für ein Eiermatch – kein Tempo, null Ideen, reiner Schlafwagenfußball!', '[{"kategorie": "wörtlich", "text": "\"Was für ein unterirdisches Fußballmatch – kein Tempo, null Ideen, reiner Schlafwagenfußball!\"  2. Was für ein Grottenkick – kein Tempo, null Ideen, das war Kreisklasse auf Standgas!  3. Was für eine Gurkenpartie – so lahm, da hätte selbst das Gras drunter einschlafen können!"}]'::jsonb, ''),
  ('mit-dem-ogrooslschmaeae-brauchsd-ma-ned-kumma', 'Mit dem Ogrooslschmää brauchsd ma ned kumma!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit diesem Abgraselschmäh brauchst du mir nicht zu kommen!', '[{"kategorie": "wörtlich", "text": "\"Mit dieser billigen Masche brauchst du mir nicht zu kommen!\"  2. Diesen 08/15-Trick kannst du dir bei mir sparen!  3. Komm mir nicht mit solch uralten Taschenspielertricks!"}]'::jsonb, ''),
  ('dea-reissd-ogrooslschmaeae-auf-friidhofsnivoo', 'Dea reissd Ogrooslschmää auf Friidhofsnivoo!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der reißt Abgraselschmäh auf Friedhofsniveau!', '[{"kategorie": "wörtlich", "text": "\"Der reißt unterirdische Witze auf Friedhofsniveau!\"  2. Der serviert Humor aus der Gruft – lauwarm und ohne Pointe!  3. Wenn der Witze erzählt, graben sich selbst die Toten freiwillig noch tiefer ein!"}]'::jsonb, ''),
  ('mit-dem-eiaschmaeae-brauchsd-ma-ned-kumma', 'Mit dem Eiaschmää brauchsd ma ned kumma!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit diesem Eierschmäh brauchst du mir nicht zu kommen!', '[{"kategorie": "wörtlich", "text": "\"Mit dieser billigen Masche brauchst du mir nicht zu kommen!\"  2. Diesen 08/15-Trick kannst du dir bei mir sparen!  3. Komm mir nicht mit solch uralten Taschenspielertricks!"}]'::jsonb, ''),
  ('dea-reissd-eiaschmaeae-auf-friidhofsnivoo', 'Dea reissd Eiaschmää auf Friidhofsnivoo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der reißt Eierschmäh auf Friedhofsniveau!', '[{"kategorie": "wörtlich", "text": "\"Der reißt unterirdische Witze auf Friedhofsniveau!\"  2. Der serviert Humor aus der Gruft – lauwarm und ohne Pointe!  3. Wenn der Witze erzählt, graben sich selbst die Toten freiwillig noch tiefer ein!"}]'::jsonb, ''),
  ('dea-ogrooslvarein-hod-mea-treena-vaschlissn-ois-boina', 'Dea Ogrooslvarein hod mea Treena vaschlissn ois Boina!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Dieser Abgraselverein hat mehr Trainer verschlissen als Bälle!', '[{"kategorie": "wörtlich", "text": "\"Dieser unterirdische Fußballverein hat mehr Trainer verschlissen als Bälle!\"  2. Bei diesem Kellerverein wechseln sie die Trainer öfter als die Eckfahnen!  3. Dieser Chaosklub hat mehr Trainer verbraucht als manche Leute Unterwäsche!"}]'::jsonb, ''),
  ('ea-nennds-biidschbody-wia-soong-dazua-ogroosltarzan-mit-sonnanbraund', 'Ea nennds ''Biidschbody'' - wia soong dazua ''Ogroosltarzan mit Sonnanbraund!''', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Er nennt es ''Beachbody'' - wir sagen dazu ''Abgraseltarzan mit Sonnenbrand''!', '[{"kategorie": "wörtlich", "text": "\"Er nennt es ''Beachbody'' - wir sagen dazu ''abgepflückter Spargeltarzan mit Sonnenbrand''!\"  2. Er sagt Strandfigur – wir sagen: [[Powidltarzan]] mit Sonnenstich"}, {"kategorie": "", "text": "Er sieht aus wie ein abgepflückter Spargel in Badehose – und fühlt sich wie ein Gott!"}]'::jsonb, ''),
  ('dea-oobrochane-kaufd-si-seine-untagattn-heit-no-in-da-kindaobtaeulung', 'Dea Oobrochane kaufd si seine Untagattn heit no in da Kindaobtäulung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Abgebrochene kauft sich seine Untergatten heute noch in der Kinderabteilung!', '[{"kategorie": "wörtlich", "text": "\"Dieser ''abgebrochene Zweibeiner'' kauft sich seine Unterhose heute noch in der Kinderabteilung!\"  2. Wenn dieser [[Meterprügel]] Unterhosen kaufen geht, fragt die Verkäuferin, wo die Mama ist!  3. Dieser [[Buttenzwerg]] shoppt seine Unterwäsche heute noch dort, wo andere Lauflernschuhe kaufen!"}]'::jsonb, ''),
  ('in-letztn-oodruck', 'in letztn Oodruck', '', '', '', 'Wiener Sprüche, die sitzen!', 'im letzten Abdruck', '[{"kategorie": "wörtlich", "text": "\"auf den letzten Drücker\""}, {"kategorie": "", "text": "im letzten Moment"}, {"kategorie": "", "text": "auf dem letzten Zacken,  4. gerade noch rechtzeitig, \"kurz vor knapp\", in letzter Sekunde"}]'::jsonb, 'I hobs in letztn Oodruck no gschofft!'),
