  ('hawai-ananas', 'Hawai-Ananas', 'die', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Hawai-Ananas', '[{"kategorie": "wörtlich", "text": "\"Ananas aus Hawai\" (\"ananas comosus\", ursprünglich von Tupí-Guaraní (indigene Sprache Brasiliens): \"nana\"=\"exzellente Frucht\")"}, {"kategorie": "allg.", "text": "Ananasfrucht (Zur Erklärung: Was in Deutschland die \"Ananas\" ist, heißt auf Wienerisch \"Hawai-Ananas\". Unter [[Ananas]] versteht der Wiener dagegen \"die Erdbeere\", also die große Garten- oder Felderdbeere)"}]'::jsonb, ''),
