  ('mei-konto-is-gschbead-jetzt-bin-i-uandlich-bediind', 'Mei Konto is gschbead, jetzt bin I uandlich bediind!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mein Konto ist gesperrt - jetzt bin ich ordentlich bedient!', '[{"kategorie": "wörtlich", "text": "\"Mein Konto ist gesperrt - jetzt bin ich so richtig bedient!\"  2. Mein Konto ist gesperrt - jetzt sitze ich ordentlich in der Klemme!  3. Mein Konto ist gesperrt - jetzt bin ich geliefert!"}]'::jsonb, ''),
  ('mei-konto-is-gschbead-jetzt-bin-i-uandlich-bediniiad', 'Mei Konto is gschbead, jetzt bin I uandlich bediniiad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mein Konto ist gesperrt - jetzt bin ich ordentlich bediniert!', '[{"kategorie": "scherzhafte Verballhornung von à\"bedient\"", "text": "\"Mein Konto ist gesperrt - jetzt bin ich so richtig bedient!\"  2. Mein Konto ist gesperrt - jetzt sitze ich ordentlich in der Klemme!  3. Mein Konto ist gesperrt - jetzt bin ich geliefert!"}]'::jsonb, ''),
  ('ea-is-bediind-aufd-schleich', 'Ea is bediind aufd Schleich!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Er ist bedient auf den Schläuchen', '[{"kategorie": "scherzhaft für", "text": "\"Er ist nicht mehr so gut auf den Beinen!\"  2. Er hat eine Gehbehinderung!  3. Er ist nicht gut zu Fuß!"}]'::jsonb, ''),
